using System;using System.IO;using System.Linq;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests {
 [Serializable]public sealed class GuidanceFixtures{public GuidanceRow[] rows;}
 [Serializable]public sealed class GuidanceRow{public string name,transfer,nextKind;public GuidancePin[] pins;public string[] candidates,returns;}
 [Serializable]public sealed class GuidancePin{public PinnedGoal pin;public bool hasCost,valid,reached;public string kind;public double eta;public NumberData cost;}
 public sealed class GuidanceParityTests {
 [Test]public void AllActualSourcePinnedQuotesCandidatesAndReturnActionsMatch(){var f=JsonUtility.FromJson<GuidanceFixtures>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/GuidanceReferenceCases.json")));var codec=new UnitySaveCodec();foreach(var row in f.rows){var s=UnityWebImport.Validate(row.transfer);string before=codec.Encode(StateData.From(s));foreach(var test in row.pins){string label=row.name+" "+test.pin.kind+" "+test.pin.id;var q=GuidanceRules.Resolve(s,test.pin);Assert.That(q!=null,Is.EqualTo(test.valid),label);if(q==null)continue;Assert.That(q.Kind,Is.EqualTo(test.kind),label);Assert.That(q.Reached,Is.EqualTo(test.reached),label);Assert.That(q.Eta,Is.EqualTo(test.eta).Within(Math.Max(1e-6,Math.Abs(test.eta)*1e-10)),label+" ETA");if(test.hasCost){var expected=ScientificNumber.FromData(test.cost);var delta=q.Cost.CompareTo(expected)>=0?q.Cost.Subtract(expected):expected.Subtract(q.Cost);if(q.Kind=="hardware"&&!expected.IsZero)Assert.That(delta.Divide(expected).ToDouble(),Is.LessThanOrEqualTo(4e-14),label+" unchanged hardware quote formula / JS-Mono floating precision");else Assert.That(q.Cost.CompareTo(expected),Is.Zero,label+" exact goal quote");}}Assert.That(GuidanceRules.Candidates(s).Select(p=>p.kind+":"+p.id+":"+(p.hasTarget?p.target.ToString():"")),Is.EqualTo(row.candidates),row.name+" actual source candidate order");Assert.That(GuidanceRules.Next(s).Kind,Is.EqualTo(row.nextKind),row.name+" next priority");Assert.That(GuidanceRules.Return(s).Select(a=>a.Kind+(string.IsNullOrEmpty(a.Id)?"":":"+a.Id)),Is.EqualTo(row.returns),row.name+" return actions");Assert.That(codec.Encode(StateData.From(s)),Is.EqualTo(before),"Quotes must remain pure");}}
 [Test]public void PinSaveReloadAndClearingNeverBuyAndClockCompletionIsNotRepeated(){var s=Game.New(1000000);s=Game.Buy(s,"calculator");s=GuidanceRules.Pin(s,new PinnedGoal{kind="hardware",id="sbc",hasTarget=true,target=10});var credits=s.Credits;var codec=new UnitySaveCodec();var reload=codec.Decode(codec.Encode(StateData.From(s)),19).ToState();Assert.That(reload.Guidance.pinned.target,Is.EqualTo(10));Assert.That(reload.Hardware,Is.EqualTo(s.Hardware));Assert.That(reload.Credits.CompareTo(credits),Is.Zero);var cleared=GuidanceRules.Pin(reload,null);Assert.That(cleared.Guidance.hasPinned,Is.False);Assert.That(cleared.Credits.CompareTo(credits),Is.Zero);}
 [Test]public void ShortReloadKeepsUnreadReturnAndReceiptIdsStayUnique(){var s=Game.New(1000000);var first=Game.AdvanceMeasured(s,s.SavedAt+60000);ReturnReceipt.Attach(s,first.State,first.Report);long id=first.State.Return.id;var shortStep=Game.AdvanceMeasured(first.State,first.State.SavedAt+1000);ReturnReceipt.Attach(first.State,shortStep.State,shortStep.Report);Assert.That(shortStep.State.Return.id,Is.EqualTo(id));Assert.That(shortStep.State.Journal.returns.Length,Is.EqualTo(1));var next=Game.AdvanceMeasured(shortStep.State,shortStep.State.SavedAt+60000);ReturnReceipt.Attach(shortStep.State,next.State,next.Report);Assert.That(next.State.Return.id,Is.EqualTo(id),"Unread current report stays visible");Assert.That(next.State.Journal.returns.Length,Is.EqualTo(2));Assert.That(next.State.Journal.returns.Select(r=>r.id).Distinct().Count(),Is.EqualTo(2));}
 }
}
